   144	/**
   145	 * @returns a map where the keys are policyIDs and the values are BrickRoads for each policy
   146	 */
   147	function getWorkspacesBrickRoads(reports: OnyxCollection<Report>, policies: OnyxCollection<Policy>, reportActions: OnyxCollection<ReportActions>): Record<string, BrickRoad> {
   148	    if (!reports) {
   149	        return {};
   150	    }
   151	
   152	    // The key in this map is the workspace id
   153	    const workspacesBrickRoadsMap: Record<string, BrickRoad> = {};
   154	    Object.values(policies ?? {}).forEach((policy) => {
   155	        // Only policies which user has access to on the list should be checked. Policies that don't have an ID and contain only information about the errors aren't displayed anywhere.
   156	        if (!policy?.id) {
   157	            return;
   158	        }
   159	
   160	        if (hasWorkspaceSettingsRBR(policy)) {
   161	            workspacesBrickRoadsMap[policy.id] = CONST.BRICK_ROAD_INDICATOR_STATUS.ERROR;
   162	        }
   163	    });
   164	
   165	    Object.values(reports).forEach((report) => {
   166	        const policyID = report?.policyID ?? CONST.POLICY.EMPTY;
   167	        if (!report || workspacesBrickRoadsMap[policyID] === CONST.BRICK_ROAD_INDICATOR_STATUS.ERROR) {
   168	            return;
   169	        }
   170	        const workspaceBrickRoad = getBrickRoadForPolicy(report, reportActions);
   171	
   172	        if (!workspaceBrickRoad && !!workspacesBrickRoadsMap[policyID]) {
   173	            return;
   174	        }
   175	
   176	        workspacesBrickRoadsMap[policyID] = workspaceBrickRoad;
   177	    });
   178	
   179	    return workspacesBrickRoadsMap;
   180	}
